class Solution:
    def tictactoe(self, moves: List[List[int]]) -> str:
        wins = [
            [(0, 0), (0, 1), (0, 2)],
            [(1, 0), (1, 1), (1, 2)],
            [(2, 0), (2, 1), (2, 2)],
            [(0, 0), (1, 0), (2, 0)],
            [(0, 1), (1, 1), (2, 1)],
            [(0, 2), (1, 2), (2, 2)],
            [(0, 0), (1, 1), (2, 2)],
            [(0, 2), (1, 1), (2, 0)],
        ]

        def checkWin(S):
            for win in wins:
                flag = True
                for pos in win:
                    if pos not in S:
                        flag = False
                        break
                if flag:
                    return True
            return False

        A, B = set(), set()
        for i, (x, y) in enumerate(moves):
            if i % 2 == 0:
                A.add((x, y))
            else:
                B.add((x, y))

        if checkWin(A):
            return 'A'
        elif checkWin(B):
            return 'B'

        return "Draw" if len(moves) == 9 else "Pending"

class Solution:
    def subtractProductAndSum(self, n: int) -> int:
        n_to_list = list(str(n))

        sum_of_digits = 0 
        for num in n_to_list:
            sum_of_digits = sum_of_digits + int(num)

        product_of_digits = 1
        for num in n_to_list:
            product_of_digits = product_of_digits * int(num)

        answer = product_of_digits - sum_of_digits

        return answer

